const asyncHandler = require('../middleware/async');
const ErrorResponse = require('../utils/errorResponse');
const Inventory = require('../models/Inventory');

// @desc    Get all inventory
// @route   GET /api/inventory
// @access  Public
exports.getAllInventory = asyncHandler(async (req, res, next) => {
  res.status(200).json({
    success: true,
    count: await Inventory.count(),
    data: await Inventory.findAll()
  });
});

// @desc    Get single inventory item
// @route   GET /api/inventory/:id
// @access  Public
exports.getInventoryById = asyncHandler(async (req, res, next) => {
  const item = await Inventory.findByPk(req.params.id);
  if (!item) {
    return next(new ErrorResponse(`Inventory item not found with id ${req.params.id}`, 404));
  }
  res.status(200).json({ success: true, data: item });
});

// @desc    Create new inventory item
// @route   POST /api/inventory
// @access  Private (admin, rental_manager, operations_staff)
exports.createInventory = asyncHandler(async (req, res, next) => {
  const item = await Inventory.create(req);
  res.status(201).json({ success: true, data: item });
});

// @desc    Update inventory item
// @route   PUT /api/inventory/:id
// @access  Private (admin, rental_manager, operations_staff)
exports.updateInventory = asyncHandler(async (req, res, next) => {
  let item = await Inventory.findByPk(req.params.id);
  if (!item) {
    return next(new ErrorResponse(`Inventory item not found with id ${req.params.id}`, 404));
  }
  item = await item.update(req.body);
  res.status(200).json({ success: true, data: item });
});

// @desc    Delete inventory item
// @route   DELETE /api/inventory/:id
// @access  Private (admin, rental_manager, operations_staff)
exports.deleteInventory = asyncHandler(async (req, res, next) => {
  const item = await Inventory.findByPk(req.params.id);
  if (!item) {
    return next(new ErrorResponse(`Inventory item not found with id ${req.params.id}`, 404));
  }
  await item.destroy();
  res.status(200).json({ success: true, data: {} });
});

