const asyncHandler = require('../middleware/async');
const ErrorResponse = require('../utils/errorResponse');
const Customer = require('../models/Customer');
const User = require('../models/User');

// @desc    Get all customers
// @route   GET /api/customers
// @access  Private (admin, rental_manager, sales_rep, accounting)
exports.getAllCustomers = asyncHandler(async (req, res, next) => {
  const customers = await Customer.findAll({
    include: [{ model: User, attributes: ['id', 'name', 'email'] }]
  });
  res.status(200).json({ success: true, count: customers.length, data: customers });
});

// @desc    Get single customer
// @route   GET /api/customers/:id
// @access  Private (admin, rental_manager, sales_rep, accounting)
exports.getCustomerById = asyncHandler(async (req, res, next) => {
  const customer = await Customer.findByPk(req.params.id, {
    include: [{ model: User, attributes: ['id', 'name', 'email'] }]
  });
  if (!customer) {
    return next(new ErrorResponse(`Customer not found with id ${req.params.id}`, 404));
  }
  res.status(200).json({ success: true, data: customer });
});

// @desc    Create new customer
// @route   POST /api/customers
// @access  Private (admin, rental_manager, sales_rep)
exports.createCustomer = asyncHandler(async (req, res, next) => {
  // Expect userId in body (the user account linked)
  const customer = await Customer.create(req.body);
  res.status(201).json({ success: true, data: customer });
});

// @desc    Update customer
// @route   PUT /api/customers/:id
// @access  Private (admin, rental_manager, sales_rep)
exports.updateCustomer = asyncHandler(async (req, res, next) => {
  let customer = await Customer.findByPk(req.params.id);
  if (!customer) {
    return next(new ErrorResponse(`Customer not found with id ${req.params.id}`, 404));
  }
  customer = await customer.update(req.body);
  res.status(200).json({ success: true, data: customer });
});

// @desc    Delete customer
// @route   DELETE /api/customers/:id
// @access  Private (admin only)
exports.deleteCustomer = asyncHandler(async (req, res, next) => {
  const customer = await Customer.findByPk(req.params.id);
  if (!customer) {
    return next(new ErrorResponse(`Customer not found with id ${req.params.id}`, 404));
  }
  await customer.destroy();
  res.status(200).json({ success: true, data: {} });
});

// @desc    Customer self-registration (public)
// @route   POST /api/customers/register
// @access  Public
exports.customerRegister = asyncHandler(async (req, res, next) => {
  // Expect: user details (name, email, password) and company details
  const { name, email, password, companyName, gstVatNumber, industryType, phone } = req.body;

  // 1. Create user record with role 'customer'
  const user = await User.create({ name, email, password, role: 'customer' });

  // 2. Create customer profile linked to user
  const customer = await Customer.create({
    userId: user.id,
    companyName,
    gstVatNumber,
    industryType,
    // other fields can be added
  });

  res.status(201).json({ success: true, data: { user, customer } });
});

