const asyncHandler = require('../middleware/async');
const ErrorResponse = require('../utils/errorResponse');
const Rental = require('../models/Rental');
const Inventory = require('../models/Inventory');
const Customer = require('../models/Customer');

// @desc    Get all rentals
// @route   GET /api/rentals
// @access  Private (admin, rental_manager, operations_staff, sales_rep)
exports.getAllRentals = asyncHandler(async (req, res, next) => {
  const rentals = await Rental.findAll({
    include: [
      { model: Inventory, as: 'inventory' },
      { model: Customer, as: 'customer' }
    ]
  });
  res.status(200).json({ success: true, count: rentals.length, data: rentals });
});

// @desc    Get single rental
// @route   GET /api/rentals/:id
// @access  Private (admin, rental_manager, operations_staff, sales_rep)
exports.getRentalById = asyncHandler(async (req, res, next) => {
  const rental = await Rental.findByPk(req.params.id, {
    include: [
      { model: Inventory, as: 'inventory' },
      { model: Customer, as: 'customer' }
    ]
  });
  if (!rental) {
    return next(new ErrorResponse(`Rental not found with id ${req.params.id}`, 404));
  }
  res.status(200).json({ success: true, data: rental });
});

// @desc    Create rental
// @route   POST /api/rentals
// @access  Private (admin, rental_manager, sales_rep)
exports.createRental = asyncHandler(async (req, res, next) => {
  const { inventoryId, customerId, rentalStartDate, rentalEndDate, rentalRate, securityDeposit, notes } = req.body;

  // Check inventory availability
  const inventoryItem = await Inventory.findByPk(inventoryId);
  if (!inventoryItem) {
    return next(new ErrorResponse(`Inventory item not found with id ${inventoryId}`, 404));
  }
  if (inventoryItem.status !== 'available') {
    return next(new ErrorResponse(`Inventory item is not available for rental`, 400));
  }

  // Check customer exists
  const customer = await Customer.findByPk(customerId);
  if (!customer) {
    return next(new ErrorResponse(`Customer not found with id ${customerId}`, 404));
  }

  // Calculate total amount (simplified: daily rate * days)
  const start = new Date(rentalStartDate);
  const end = new Date(rentalEndDate);
  const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
  const totalAmount = (rentalRate * days) + (securityDeposit || 0);

  // Create rental
  const rental = await Rental.create({
    inventoryId,
    customerId,
    rentalStartDate,
    rentalEndDate,
    rentalRate,
    securityDeposit: securityDeposit || 0,
    totalAmount,
    notes
  });

  // Update inventory status to rented
  await inventoryItem.update({ status: 'rented' });

  res.status(201).json({ success: true, data: rental });
});

// @desc    Update rental
// @route   PUT /api/rentals/:id
// @access  Private (admin, rental_manager, operations_staff, sales_rep)
exports.updateRental = asyncHandler(async (req, res, next) => {
  let rental = await Rental.findByPk(req.params.id);
  if (!rental) {
    return next(new ErrorResponse(`Rental not found with id ${req.params.id}`, 404));
  }

  // Update rental details
  rental = await rental.update(req.body);
  res.status(200).json({ success: true, data: rental });
});

// @desc    Delete rental
// @route   DELETE /api/rentals/:id
// @access  Private (admin only)
exports.deleteRental = asyncHandler(async (req, res, next) => {
  const rental = await Rental.findByPk(req.params.id);
  if (!rental) {
    return next(new ErrorResponse(`Rental not found with id ${req.params.id}`, 404));
  }

  // If rental is active, set inventory back to available
  if (rental.status === 'active') {
    const inventoryItem = await Inventory.findByPk(rental.inventoryId);
    if (inventoryItem) {
      await inventoryItem.update({ status: 'available' });
    }
  }

  await rental.destroy();
  res.status(200).json({ success: true, data: {} });
});

// @desc    Return equipment
// @route   PUT /api/rentals/:id/return
// @access  Private (admin, rental_manager, operations_staff)
exports.returnEquipment = asyncHandler(async (req, res, next) => {
  const rental = await Rental.findByPk(req.params.id);
  if (!rental) {
    return next(new ErrorResponse(`Rental not found with id ${req.params.id}`, 404));
  }

  if (rental.status !== 'active') {
    return next(new ErrorResponse(`Rental is not active`, 400));
  }

  // Set actual return date
  rental.actualReturnDate = new Date();
  // Update status to completed
  rental.status = 'completed';
  await rental.save();

  // Update inventory status to available (assuming it's returned in good condition)
  const inventoryItem = await Inventory.findByPk(rental.inventoryId);
  if (inventoryItem) {
    await inventoryItem.update({ status: 'available' });
  }

  res.status(200).json({ success: true, data: rental });
});

// @desc    Extend rental
// @route   PUT /api/rentals/:id/extend
// @access  Private (admin, rental_manager, sales_rep)
exports.extendRental = asyncHandler(async (req, res, next) => {
  const rental = await Rental.findByPk(req.params.id);
  if (!rental) {
    return next(new ErrorResponse(`Rental not found with id ${req.params.id}`, 404));
  }

  if (rental.status !== 'active') {
    return next(new ErrorResponse(`Rental is not active`, 400));
  }

  const { rentalEndDate } = req.body;
  if (!rentalEndDate) {
    return next(new ErrorResponse(`Please provide a new rental end date`, 400));
  }

  // Update end date and recalculate total amount
  const start = new Date(rental.rentalStartDate);
  const end = new Date(rentalEndDate);
  const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
  const additionalDays = days - Math.ceil((new Date(rental.rentalEndDate) - start))); // This is messy, let's simplify

  // Instead: have: (we) - old deposit? Actually, we can just recalculate total from scratch.
  const rentalRate = rental.rentalRate;
  const securityDeposit = rental.securityDeposit;
  const totalAmount = (rentalRate * days) + securityDeposit;

  rental.rentalEndDate = rentalEndDate;
  rental.totalAmount = totalAmount;
  await rental.save();

  res.status(200).json({ success: true, data: rental });
});

// @desc    Get my rentals (for customer portal)
// @route   GET /api/rentals/my
// @access  Private (customer)
exports.getMyRentals = asyncHandler(async (req, res, next) => {
  // We assume the customer profile is linked to the user via req.user.id
  // But we don't have the customer id in the user. We need to get the customer record for the user.
  // However, in the auth middleware, we set req.user from the User model.
  // We need to get the customer record associated with this user.
  const customer = await Customer.findOne({ where: { userId: req.user.id } });
  if (!customer) {
    return next(new ErrorResponse(`Customer profile not found for user`, 404));
  }

  const rentals = await Rental.findAll({
    where: { customerId: customer.id },
    include: [
      { model: Inventory, as: 'inventory' }
    ]
  });
  res.status(200).json({ success: true, count: rentals.length, data: rentals });
});

// @desc    Get my rental by id (for customer portal)
// @route   GET /api/rentals/my/:id
// @access  Private (customer)
exports.getMyRentalById = asyncHandler(async (req, res, next) => {
  const customer = await Customer.findOne({ where: { userId: req.user.id } });
  if (!customer) {
    return next(new ErrorResponse(`Customer profile not found for user`, 404));
  }

  const rental = await Rental.findOne({
    where: { id: req.params.id, customerId: customer.id },
    include: [
      { model: Inventory, as: 'inventory' }
    ]
  });
  if (!rental) {
    return next(new ErrorResponse(`Rental not found or not authorized`, 404));
  }
  res.status(200).json({ success: true, data: rental });
});

