  if (rental.status !== 'active') {
    return next(new ErrorResponse(`Rental is not active`, 400));
  }

  const { rentalEndDate } = req.body;
  if (!rentalEndDate) {
    return next(new ErrorResponse(`Please provide a new rental end date`, 400));
  }

  // Update end date and recalculate total amount
  const start = new Date(rental.rentalStartDate);
  const end = new Date(rentalEndDate);
  const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
  const additionalDays = days - Math.ceil((new Date(rental.rentalEndDate) - start))); // This is messy, let's simplify

  // Instead: have: (we) - old deposit? Actually, we can just recalculate total from scratch.
  const rentalRate = rental.rentalRate;
  const securityDeposit = rental.securityDeposit;
  const totalAmount = (rentalRate * days) + securityDeposit;

  rental.rentalEndDate = rentalEndDate;
  rental.totalAmount = totalAmount;
  await rental.save();

  res.status(200).json({ success: true, data: rental });
});

// @desc    Get my rentals (for customer portal)
// @route   GET /api/rentals/my
// @access  Private (customer)
exports.getMyRentals = asyncHandler(async (req, res, next) => {
  // We assume the customer profile is linked to the user via req.user.id
  // But we don't have the customer id in the user. We need to get the customer record for the user.
  // However, in the auth middleware, we set req.user from the User model.
  // We need to get the customer record associated with this user.
  const customer = await Customer.findOne({ where: { userId: req.user.id } });
  if (!customer) {
    return next(new ErrorResponse(`Customer profile not found for user`, 404));
  }

  const rentals = await Rental.findAll({
    where: { customerId: customer.id },
    include: [
      { model: Inventory, as: 'inventory' }
    ]
  });
  res.status(200).json({ success: true, count: rentals.length, data: rentals });
});

// @desc    Get my rental by id (for customer portal)
// @route   GET /api/rentals/my/:id
// @access  Private (customer)
exports.getMyRentalById = asyncHandler(async (req, res, next) => {
  const customer = await Customer.findOne({ where: { userId: req.user.id } });
  if (!customer) {
    return next(new ErrorResponse(`Customer profile not found for user`, 404));
  }

  const rental = await Rental.findOne({
    where: { id: req.params.id, customerId: customer.id },
    include: [
      { model: Inventory, as: 'inventory' }
    ]
  });
  if (!rental) {
    return next(new ErrorResponse(`Rental not found or not authorized`, 404));
  }
  res.status(200).json({ success: true, data: rental });
});

