const express = require('express');
const router = express.Router();
const billingController = require('../controllers/billingController');
const { protect, authorize } = require('../middleware/auth');

router.use(protect);

// Customer routes (limited to their own billings)
router.get('/my', authorize('customer'), billingController.getMyBillings);
router.get('/my/:id', authorize('customer'), billingController.getMyBillingById);

// Staff & admin routes
router.use(authorize('admin', 'rental_manager', 'accounting', 'sales_rep'));
router.route('/')
  .get(billingController.getAllBillings)
  .post(billingController.createBilling);

router.route('/:id')
  .get(billingController.getBillingById)
  .put(billingController.updateBilling)
  .delete(billingController.deleteBilling);

router.route('/:id/payment')
  .put(billingController.recordPayment);

module.exports = router;

