import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';

export const Navbar = () => {
  const { user, logout } = useAuth();
  const location = useLocation();

  const navItems = [
    { name: 'Dashboard', path: '/dashboard', icon: '📊' },
    { name: 'Inventory', path: '/inventory', icon: '📦' },
    { name: 'Customers', path: '/customers', icon: '👥' },
    { name: 'Rentals', path: '/rentals', icon: '🔁' },
    { name: 'Billing', path: '/billing', icon: '💰' },
    { name: 'Maintenance', path: '/maintenance', icon: '🔧' },
    { name: 'Reports', path: '/reports', icon: '📈' },
  ];

  const customerNavItems = [
    { name: 'Customer Portal', path: '/customer-portal', icon: '🏪' },
  ];

  const isAdmin = user && user.role === 'admin';
  const isStaff = user && ['admin', 'rental_manager', 'sales_rep', 'operations_staff', 'accounting'].includes(user.role);
  const isCustomer = user && user.role === 'customer';

  return (
    <nav className="bg-gray-900/80 backdrop-blur-sm border-b border-gray-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-wrap items-center justify-between h-16">
        <div className="flex-shrink-0 flex items-center">
          <Link to="/" className="text-2xl font-bold text-white flex items-center gap-2">
            <span className="text-blue-400">💻</span>
            <span>RentalSys</span>
          </Link>
        </div>
        <div className="hidden md:flex md:items-center md:w-auto flex-1">
          <div className="flex-1 flex justify-center md:justify-start">
            <ul className="flex flex-wrap -mx-3 text-base font-medium">
              {navItems.map((item) => (
                <li key={item.path} className="px-3 py-2 rounded-md">
                  <Link
                    to={item.path}
                    className={`${location.pathname === item.path
                      ? 'bg-gray-800 text-white'
                      : 'text-gray-300 hover:text-white hover:bg-gray-800'
                    } flex items-center gap-1 px-3 py-2 rounded-md`}
                  >
                    {item.icon}
                    <span>{item.name}</span>
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        </div>
        <div className="flex items-center space-x-4">
          {!user ? (
            <Link to="/login" className="btn-primary px-4 py-2 rounded-md text-sm font-medium">Login</Link>
          ) : (
            <>
              {isCustomer && (
                <>
                  <Link to="/customer-portal" className="flex items-center gap-2 text-gray-300 hover:text-white">
                    <span>🏪</span>
                    <span>Customer Portal</span>
                  </Link>
                </>
              )}
              {!isCustomer && (
                <>
                  <div className="relative">
                    <button
                      onClick={(e) => e.preventDefault()}
                      className="flex items-center gap-2 text-gray-300 hover:text-white"
                    >
                      <span>👤</span>
                      <span>{user?.name}</span>
                      <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                      </svg>
                    </button>
                    <div className="absolute right-0 mt-2 w-48 bg-gray-800/80 backdrop-blur-sm border border-gray-700 rounded-md shadow-lg z-20 hidden">
                      <div className="py-2">
                        <a href="#" className="block px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">Profile</a>
                        <a href="#" className="block px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">Settings</a>
                        <button onClick={logout} className="block w-full text-left px-4 py-2 text-sm text-gray-300 hover:bg-gray-700">
                          Logout
                        </button>
                      </div>
                    </div>
                  </div>
                </>
              )}
            </>
          )}
        </div>
      </div>
    </nav>
  );
};

// Simple button component
const Btn = ({ children, ...props }) => (
  <button className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded transition {...props}">
    {children}
  </button>
);

