import React from 'react';

export const StatCard = ({ title, value, icon, trend, color }) => {
  const colorMap = {
    blue: 'border-blue-500 bg-blue-900/20 text-blue-400',
    green: 'border-green-500 bg-green-900/20 text-green-400',
    purple: 'border-purple-500 bg-purple-900/20 text-purple-400',
    orange: 'border-orange-500 bg-orange-900/20 text-orange-400',
    red: 'border-red-500 bg-red-900/20 text-red-400',
  };

  const bgClass = colorMap[color] || colorMap.blue;

  return (
    <div className={`flex flex-col items-start p-4 rounded-lg border ${bgClass} hover:shadow-lg transition-shadow duration-300`}>
      <div className="flex items-center gap-3 mb-3">
        <div className="text-2xl">{icon}</div>
        <h3 className="text-sm font-medium text-gray-400">{title}</h3>
      </div>
      <p className="text-2xl font-bold w-full">{value}</p>
      {trend && (
        <p className="text-sm flex items-center gap-1 mt-1">
          <span className={trend.startsWith('+') ? 'text-green-500' : 'text-red-500'}>
            {trend}
          </span>
        </p>
      )}
    </div>
  );
};

