import React from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

export const HeroSection = ({ title, subtitle, className = '' }) => {
  return (
    <section className={`relative py-20 bg-gray-900 overflow-hidden ${className}`}>
      {/* Animated 3D background */}
      <div className="absolute inset-0 -z-10">
        <Canvas style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%' }}>
          <ambientLight intensity={0.5} />
          <directionalLight position={[10, 20, 10]} intensity={1} />
          {/* Simple 3D shape - could be a stylized server rack */}
          <mesh position={[0, 0, 0]} rotation={[0, Math.PI / 4, 0]}>
            <boxGeometry args={[2, 1, 1.5]} />
            <meshStandardMaterial color="#0ea5e9" metalness={0.2} roughness={0.5} />
          </mesh>
          {/* Floating particles */}
          <points>
            <bufferGeometry>
              <float32Attribute
                name="position"
                count={100}
                itemSize={3}
                // We'll generate random positions in useEffect in real app
                // For now, placeholder
                data={Array(100 * 3).fill(0).map(() => Math.random() * 2 - 1)}
              />
            </bufferGeometry>
            <pointsMaterial
              size={0.02}
              color={0x0ea5e9}
              transparent
              opacity={0.6}
            />
          </points>
          <OrbitControls enableZoom={false} enablePan={false} enableRotate={false} />
        </Canvas>
      </div>

      <div className="relative z-10 max-w-4xl mx-auto px-4 text-center">
        <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-cyan-400">
          {title}
        </h1>
        <p className="text-xl md:text-2xl max-w-xl mx-auto text-gray-300">
          {subtitle}
        </p>
      </div>
    </section>
  );
};

