          condition: 'refurbished',
          location: 'Warehouse A',
          status: 'available',
          acquisitionDate: '2023-05-15',
        },
        {
          id: 2,
          itemId: 'INV-002',
          type: 'laptop',
          brand: 'Lenovo',
          model: 'ThinkPad P15',
