import React, { useState, useEffect } from 'react';
import { Table } from '../components/Table';
import { Button } from '../components/Button';
import { Link } from 'react-router-dom';
import { HeroSection } from '../components/HeroSection';

export const MaintenancePage = () => {
  const [maintenance, setMaintenance] = useState([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('');

  useEffect(() => {
    // Simulate API call
    setTimeout(() => {
      const sampleData = [
        {
          id: 1,
          equipment: 'Dell PowerEdge R740',
          type: 'Preventive',
          date: '2023-10-10',
          description: 'Quarterly inspection and cleaning',
          status: 'completed',
          cost: '$150',
        },
        {
          id: 2,
          equipment: 'Lenovo ThinkPad P15',
          type: 'Repair',
          date: '2023-10-05',
          description: 'Screen replacement',
          status: 'in-progress',
          cost: '$0', // warranty
        },
        {
          id: 3,
          equipment: 'Cisco Catalyst 9300',
          type: 'Upgrade',
          date: '2023-10-15',
          description: 'Firmware update',
          status: 'scheduled',
          cost: '$0',
        },
      ];
      setMaintenance(sampleData);
      setLoading(false);
    }, 1000);
  }, []);

  const columns = [
    { header: 'Equipment', accessor: 'equipment' },
    { header: 'Type', accessor: 'type' },
    { header: 'Date', accessor: 'date' },
    { header: 'Description', accessor: 'description' },
    { header: 'Status', accessor: 'status' },
    { header: 'Cost', accessor: 'cost' },
    { header: 'Actions', accessor: 'actions', className: 'text-right' },
  ];

  const filteredMaintenance = maintenance.filter((m) => {
    if (!statusFilter) return true;
    return m.status === statusFilter;
  });

  return (
    <>
      <HeroSection
        title="Maintenance Management"
        subtitle="Track equipment maintenance, repairs, and service schedules"
        className="pb-0"
      />
      <div className="px-4 py-8 sm:px-6 lg:px-8">
        {/* Filter and actions */}
        <div className="mb-6 flex flex-wrap items-center justify-between">
          <div className="flex items-center space-x-3">
            <h2 className="text-xl font-semibold text-white">Maintenance</h2>
          </div>
          <div className="flex items-center space-x-3">
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-3 py-2 rounded-md border border-gray-600 bg-gray-800 text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="">All Statuses</option>
              <option value="scheduled">Scheduled</option>
              <option value="in-progress">In Progress</option>
              <option value="completed">Completed</option>
              <option value="cancelled">Cancelled</option>
            </select>
            <Link to="/maintenance/new" className="btn-primary px-4 py-2">
              Schedule Maintenance
            </Link>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 mb-6">
          <div className="bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700/50 p-4">
            <h3 className="text-sm font-medium text-gray-400">Scheduled</h3>
            <p className="text-2xl font-bold text-blue-500">{maintenance.filter((m) => m.status === 'scheduled()) }
          </div>
          <div className="bg-gray-800/50 backdrop-blur-sm rounded-xl border border-gray-700/50 p-4">
            <h3 className="text-sm font-medium text-gray-400">In Progress</h3>
            <p className="text-2xl font-bold text-yellow-500">{maintenance.filter((m) => m.status === 'in-progress').length}</p>
          </div>
