            />
          </div>
        </div>

        {/* Actions */}
        <div className="flex flex-wrap gap-4">
          <Link to="/rentals/new" className="btn-primary px-4 py-2">
            Request New Rental
          </Link>
          <Button onClick={() => alert('Update profile functionality')}>
            Update Profile
          </Button>
          <Button variant="secondary" onClick={() => alert('Support ticket opened')}>
            Contact Support
          </Button>
        </div>
      </div>
    </>
  );
};

